 replies:[{id:'q1',name:'首次问候',shortcut:'/hello',category:'接待',scope:'团队',content:'您好，感谢联系！请问您希望了解哪项服务？'},{id:'q2',name:'报价确认',shortcut:'/price',category:'销售',scope:'个人',content:'您好 {{name}}，我们会根据确认的服务范围提供报价。方便补充您的具体需求吗？'},{id:'q3',name:'预约提醒',shortcut:'/meeting',category:'日程',scope:'团队',content:'您好，提醒您我们已约定明天沟通，如需调整请告诉我。'}],
