 followups:[{id:'f1',name:'报价后温和跟进',status:'启用',trigger:'客户 24 小时未回复',steps:'3',enrolled:'12',next:'24 小时 → 3 天 → 7 天'},{id:'f2',name:'演示预约提醒',status:'暂停',trigger:'预约开始前 2 小时',steps:'1',enrolled:'3',next:'预约前 2 小时'}],
